import React, { useState } from "react";
import Message from "./Message";
import axios from "axios";
import { FaSpinner } from "react-icons/fa"; // Import spinner icon

const ChatBox = () => {
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false); // Loading state

  const handleSend = async () => {
    if (!input.trim()) return;

    const newMessage = { text: input, type: "user" };
    setMessages([...messages, newMessage]);
    setInput("");
    setLoading(true); // Show loading

    try {
      const res = await axios.post("http://localhost:5000/chat", { prompt: input });
      setMessages([...messages, newMessage, { text: res.data.response.parts[0].text, type: "bot" }]);
    } catch (error) {
      setMessages([...messages, newMessage, { text: "Error fetching response.", type: "bot" }]);
    } finally {
      setLoading(false); // Hide loading
    }
  };

  return (
    <div className="chat-container">
      <div className="chat-box">
        {messages.map((msg, index) => (
          <Message key={index} text={msg.text} type={msg.type} />
        ))}
        {loading && <FaSpinner className="spinner" />} {/* Show spinner */}
      </div>
      <div className="input-area">
        <textarea value={input} onChange={(e) => setInput(e.target.value)} placeholder="Ask me anything..." />
        <button onClick={handleSend}>Send</button>
      </div>
    </div>
  );
};

export default ChatBox;
